mapper.select:
SELECT CONDITION1_SEQ condition1Seq, BIZCND bizcnd, INDUTY induty, VAT_DEDUCT_YN vatDeductYn, VAT_TYPE_CODE vatTypeCode, ACCOUNT_CODE accountCode, USE_AT useAt FROM VAT_CARD_CONDITION1 WHERE 1=1
AND (BIZCND LIKE CONCAT('%', #{searchKeyword}, '%') OR INDUTY LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY CONDITION1_SEQ DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT CONDITION1_SEQ condition1Seq, BIZCND bizcnd, INDUTY induty, VAT_DEDUCT_YN vatDeductYn,
       VAT_TYPE_CODE vatTypeCode, ACCOUNT_CODE accountCode, USE_AT useAt
  FROM VAT_CARD_CONDITION1 WHERE CONDITION1_SEQ=#{value}

mapper.update:
UPDATE VAT_CARD_CONDITION1 SET BIZCND=#{bizcnd}, INDUTY=#{induty}, VAT_DEDUCT_YN=NULLIF(#{vatDeductYn},''),
       VAT_TYPE_CODE=NULLIF(#{vatTypeCode},''), ACCOUNT_CODE=NULLIF(#{accountCode},''), USE_AT=#{useAt}, LAST_UPDT_PNTTM=NOW()
 WHERE CONDITION1_SEQ=#{condition1Seq}
